// ── LIVE PLAYER VIEW SYNC (Supabase REST; no extra package required) ─────────
const SUPABASE_URL='https://pjohecwpciwexvtmvkdz.supabase.co';
const SUPABASE_ANON_KEY='sb_publishable_AJlpAmypniaLs4Zmc7ki6w_3zT1kmcQ';
const LIVE_ROOM_KEY='checkerboardLiveRoomIdV128';
function liveSyncReady(){return !!(SUPABASE_URL&&SUPABASE_ANON_KEY&&SUPABASE_URL.includes('supabase.co'));}
function makeLiveRoomId(){return `cb-${Date.now().toString(36)}-${Math.random().toString(36).slice(2,8)}`;}
function getCourtModeFromUrl(){try{const p=new URLSearchParams(window.location.search||'');const c=p.get('court');const h=p.get('host');if(c&&h)return {court:Number(c),host:h};}catch{}return null;}
function courtRoomId(base,n){return `${base}__court${n}`;}
function courtStandingsRoomId(base){return `${base}__standings`;}
function buildCourtLink(n,base){const b=window.location.origin+window.location.pathname;return `${b}?court=${n}&host=${encodeURIComponent(base)}`;}
function getPersistentLiveRoomId(){
  const cm=getCourtModeFromUrl();
  if(cm&&cm.host&&cm.court)return courtRoomId(cm.host,cm.court);
  try{
    let room=localStorage.getItem(LIVE_ROOM_KEY);
    if(!room){room=makeLiveRoomId();localStorage.setItem(LIVE_ROOM_KEY,room);}
    return room;
  }catch{return 'cb-checkerboard-live';}
}
function getLiveRoomFromUrl(){try{return new URLSearchParams(window.location.search||'').get('liveRoom')||'';}catch{return '';} }
function buildLivePlayerViewUrl(roomId){const room=roomId||getPersistentLiveRoomId();const base=window.location.origin+window.location.pathname;return `${base}?liveRoom=${encodeURIComponent(room)}`;}
function supabaseRestHeaders(extra={}){
  // Supabase REST expects both apikey and Authorization for browser writes with RLS.
  // This works for the new sb_publishable_ keys as well as legacy eyJ anon keys.
  const key=String(SUPABASE_ANON_KEY||'').trim();
  return {
    apikey:key,
    Authorization:`Bearer ${key}`,
    ...extra
  };
}
async function writeLivePlayerRoom(roomId,mode,payload){
  if(!roomId||!liveSyncReady()) return false;
  const key=String(SUPABASE_ANON_KEY||'').trim();
  const row={room_id:roomId,mode,payload:{...payload,liveRoomId:roomId,updatedAt:new Date().toISOString()},updated_at:new Date().toISOString()};
  // v134: send the key three ways: apikey header, bearer header, and apikey URL param.
  // This removes the previous misleading fallback where the last failed attempt had no apikey header.
  const endpoint=`${SUPABASE_URL}/rest/v1/live_sessions?on_conflict=room_id&apikey=${encodeURIComponent(key)}`;
  const headers={
    apikey:key,
    Authorization:`Bearer ${key}`,
    'Content-Type':'application/json',
    Prefer:'resolution=merge-duplicates,return=representation'
  };
  try{
    const res=await fetch(endpoint,{method:'POST',headers,body:JSON.stringify(row)});
    if(res.ok){
      let returned=null;
      try{returned=await res.json();}catch{}
      try{localStorage.setItem('checkerboardLiveLastWrite',JSON.stringify({roomId,mode,attempt:'apikey-header-and-query',returned,at:new Date().toISOString()}));localStorage.removeItem('checkerboardLiveLastError');}catch{}
      return true;
    }
    const txt=await res.text().catch(()=>'');
    const lastError=`apikey-header-and-query: HTTP ${res.status} ${txt}`;
    console.warn('Live sync write failed',lastError);
    try{localStorage.setItem('checkerboardLiveLastError',lastError);}catch{}
    return false;
  }catch(err){
    const lastError=`apikey-header-and-query: ${err?.message||String(err)}`;
    console.warn('Live sync write failed',lastError);
    try{localStorage.setItem('checkerboardLiveLastError',lastError);}catch{}
    return false;
  }
}
async function readLivePlayerRoom(roomId){
  if(!roomId||!liveSyncReady()) return null;
  try{
    const res=await fetch(`${SUPABASE_URL}/rest/v1/live_sessions?room_id=eq.${encodeURIComponent(roomId)}&select=mode,payload,updated_at&limit=1&apikey=${encodeURIComponent(String(SUPABASE_ANON_KEY||'').trim())}`,{
      headers:supabaseRestHeaders()
    });
    if(!res.ok){console.warn('Live sync read failed',res.status,await res.text().catch(()=>''));return null;}
    const rows=await res.json();
    return rows?.[0]||null;
  }catch(err){console.warn('Live sync read failed',err);return null;}
}


