        invasionInvaderOverrides,
        invasionCarryLives,
        invasionFinishLives,
        invasionFairBaseTotal:getInvasionFairBaseTotal(),
        invasionFairLivesByTeam:getInvasionFairLivesMap(invasionTeams),
