function SRStyles(){return <style>{`
.srWrap{max-width:1000px;margin:0 auto;}
.srTabs{display:flex;flex-wrap:wrap;gap:8px;margin:14px 0;}
.srTab{flex:1;min-width:140px;background:#0f1822;border:1px solid #223044;border-radius:11px;padding:11px 12px;color:#9fb0c2;font-weight:700;cursor:pointer;text-align:left;}
.srTab.on{background:#16466a;border-color:#2E6E8E;color:#eaf4fb;}
.srTab small{display:block;font-weight:500;color:#6b8299;font-size:0.72rem;margin-top:3px;}
.srBlurb{background:#0d1722;border:1px solid #223044;border-left:3px solid #2E6E8E;border-radius:10px;padding:11px 14px;color:#c5d6e6;margin-bottom:14px;line-height:1.45;}
.srGameGrid{display:grid;grid-template-columns:repeat(auto-fill,minmax(180px,1fr));gap:9px;margin-bottom:16px;}
.srGameCard{background:#0f1822;border:1px solid #223044;border-radius:11px;padding:12px 13px;color:#c5d6e6;cursor:pointer;text-align:left;}
.srGameCard.on{background:#102a1c;border-color:#1d6b3f;}
.srGameCard strong{color:#eaf4fb;display:block;margin-bottom:4px;}
.srGameCard span{font-size:0.8rem;color:#7c8ea0;line-height:1.35;}
.srDetail{background:#0b1320;border:1px solid #213247;border-radius:14px;padding:16px;margin-bottom:16px;}
.srDetail h3{margin:0 0 4px;color:#eaf4fb;}
.srObj{display:flex;flex-wrap:wrap;gap:10px;margin:10px 0;}
.srObjBox{flex:1;min-width:200px;background:#0f1822;border:1px solid #223044;border-radius:10px;padding:11px 13px;}
.srObjBox .lbl{font-size:0.72rem;text-transform:uppercase;letter-spacing:0.05em;color:#5e89b0;margin-bottom:4px;}
.srObjBox p{margin:0;color:#d7e4f0;line-height:1.4;}
.srScorer{display:flex;gap:12px;flex-wrap:wrap;margin-top:8px;}
.srSide{flex:1;min-width:220px;background:#0f1822;border:1px solid #223044;border-radius:12px;padding:14px;}
.srSide h4{margin:0 0 6px;color:#eaf4fb;}
.srNum{font-size:2.6rem;font-weight:800;line-height:1;}
.srBtnRow{display:flex;gap:8px;flex-wrap:wrap;margin-top:10px;}
.srBtn{background:#16466a;border:1px solid #2E6E8E;color:#eaf4fb;border-radius:9px;padding:9px 13px;font-weight:700;cursor:pointer;}
.srBtn.good{background:#114d2c;border-color:#1d6b3f;color:#bff0d0;}
.srBtn.ghost{background:#0b1118;border-color:#2c3c4e;color:#9fb0c2;}
.srPhase{display:inline-flex;gap:6px;align-items:center;background:#15233a;border:1px solid #294063;color:#9cc4ec;border-radius:999px;padding:5px 12px;font-weight:700;font-size:0.85rem;}
.srMuted{color:#7c8ea0;font-size:0.85rem;line-height:1.45;}
/* player display */
.srDisp{min-height:100vh;background:radial-gradient(circle at 50% 0%,#102338,#060c14 70%);color:#eaf4fb;padding:5vh 4vw;box-sizing:border-box;}
.srDispTop{text-align:center;margin-bottom:3vh;}
.srDispTop span{letter-spacing:0.14em;color:#5e89b0;font-size:1rem;}
.srDispTop h1{font-size:3rem;margin:6px 0 0;}
.srDispObj{display:flex;gap:18px;flex-wrap:wrap;justify-content:center;margin-bottom:3vh;}
.srDispCard{flex:1;min-width:300px;max-width:460px;background:#0e1d30;border:1px solid #21384e;border-radius:16px;padding:22px;}
.srDispCard .l{color:#5e89b0;text-transform:uppercase;letter-spacing:0.06em;font-size:1rem;margin-bottom:8px;}
.srDispCard .t{font-size:1.7rem;font-weight:700;line-height:1.3;}
.srDispScore{display:flex;gap:30px;justify-content:center;align-items:center;margin-bottom:2vh;}
.srDispScore .s{text-align:center;}
.srDispScore .s .n{font-size:4.5rem;font-weight:800;color:#7db8ff;line-height:1;}
.srDispScore .s .who{color:#5e89b0;font-size:1.1rem;margin-top:6px;}
.srDispBonus{text-align:center;font-size:1.3rem;color:#ffd479;}
`}</style>;}

function ServeReturnModule({setScreen,setSession,embedded=false}){
  const [tab,setTab]=useState('serve');
  const [sel,setSel]=useState('sv0');
  const [srv,setSrv]=useState(0);
  const [ret,setRet]=useState(0);
  const [phase,setPhase]=useState('Serve');
  const [undo,setUndo]=useState([]);
  const [projecting,setProjecting]=useState(()=>!!getCourtModeFromUrl());
  const [srvDb,setSrvDb]=useState('Unlimited');
  const [retDb,setRetDb]=useState('Unlimited');

  const games=SR_GAMES[tab]||[];
  const game=games.find(g=>g.id===sel)||games[0];
  const tabMeta=SR_TABS.find(t=>t.id===tab)||SR_TABS[0];

  useEffect(()=>{const first=(SR_GAMES[tab]||[])[0];if(first&&!(SR_GAMES[tab]||[]).some(g=>g.id===sel))setSel(first.id);},[tab]);

  function push(){setUndo(p=>[...p.slice(-29),{srv,ret,phase}]);}
  function addSrv(n){push();setSrv(s=>s+n);}
  function addRet(n){push();setRet(s=>s+n);}
  function doUndo(){setUndo(p=>{if(!p.length)return p;const s=p[p.length-1];setSrv(s.srv);setRet(s.ret);setPhase(s.phase);return p.slice(0,-1);});}
  function resetScore(){push();setSrv(0);setRet(0);setPhase('Serve');}
  function nextPhase(){push();setPhase(p=>p==='Serve'?'Return':p==='Return'?'Third ball':'Serve');}

  useEffect(()=>{
    if(!projecting)return;
    writeLivePlayerRoom(getPersistentLiveRoomId(),'servereturn',{
      type:'servereturn',tabLabel:tabMeta.label,
      game:game?{title:game.title,task:game.task,scoring:game.scoring,bonus:game.bonus}:null,
      serverPts:srv,returnerPts:ret,phase,showPhase:tab==='first3'
    });
  },[projecting,tab,sel,srv,ret,phase]);

  function pushPlayerView(){setProjecting(true);writeLivePlayerRoom(getPersistentLiveRoomId(),'servereturn',{type:'servereturn',tabLabel:tabMeta.label,game:game?{title:game.title,task:game.task,scoring:game.scoring,bonus:game.bonus}:null,serverPts:srv,returnerPts:ret,phase,showPhase:tab==='first3'});}
  function openPlayerView(){try{window.open(buildLivePlayerViewUrl(),'_blank');}catch{}}

  function addToSession(){
    if(!setSession||!game)return;
    setSession(prev=>appendToSessionState(prev,{id:Date.now()+Math.random(),title:'Serve & Return — '+game.title,category:'Serve & Return',format:tabMeta.label,duration:10,task:game.task,scoring:game.scoring+(game.bonus?(' Bonus: '+game.bonus):''),rationale:'Serve = affordance creation · return = affordance disruption · third ball = affordance exploitation. Trains the rally before it begins: initiative, disruption, anticipation and first-strike quality.',coach:'Reward function (did it create/deny advantage?), not textbook form. Layer constraints and DB to keep it representative.',playerFocus:game.task,layers:[],rld:tab==='read'?5:4}));
  }

  return <div className={embedded?'':'page'}>
    <SRStyles/>
    {!embedded&&<div className="pageTop"><div><h1>Serve &amp; Return™</h1><p className="mutedText">Serve = create · Return = disrupt · Third ball = exploit</p></div><button className="secondaryBtn" onClick={()=>setScreen&&setScreen('home')}>Home</button></div>}
    <div className="srWrap">
      <CoachRationale label="Why this module — the rally before the rally">
        <p>Serve and return shape the rally before it begins, yet they are routinely under-trained. In ecological terms the <strong>serve creates an affordance</strong> (an advantage to exploit), the <strong>return disrupts it</strong>, and the <strong>third ball exploits or neutralises</strong> what the first two produced. Score the <em>function</em> — did the shot create, deny or take advantage — not the textbook shape of it.</p>
      </CoachRationale>

      <div className="srTabs">
        {SR_TABS.map(t=><button key={t.id} type="button" className={'srTab'+(tab===t.id?' on':'')} onClick={()=>setTab(t.id)}>{t.label}<small>{t.id==='serve'?'length · width · disguise':t.id==='return'?'neutralise the serve':t.id==='first3'?'serve · return · third ball':'perceptual reading'}</small></button>)}
      </div>

      <div className="srBlurb">{tabMeta.blurb}</div>

      <div className="srGameGrid">
        {games.map(g=><button key={g.id} type="button" className={'srGameCard'+(sel===g.id?' on':'')} onClick={()=>setSel(g.id)}><strong>{g.title}</strong><span>{g.task}</span></button>)}
      </div>

      {game&&<div className="srDetail">
        <h3>{game.title}</h3>
        {tab==='first3'&&<div style={{margin:'4px 0 10px'}}><span className="srPhase">Phase · {phase}</span> <button type="button" className="srBtn ghost" onClick={nextPhase} style={{marginLeft:'8px'}}>Next phase →</button></div>}
        <div className="srObj">
          <div className="srObjBox"><div className="lbl">Objective</div><p>{game.task}</p></div>
          <div className="srObjBox"><div className="lbl">Scoring</div><p>{game.scoring}{game.bonus?(' '):''}{game.bonus&&<strong style={{color:'#ffd479'}}> Bonus: {game.bonus}</strong>}</p></div>
        </div>

        <div className="srScorer">
          <div className="srSide">
            <h4>Server</h4>
            <div className="srNum" style={{color:'#7db8ff'}}>{srv}</div>
            <div className="srBtnRow">{(game&&game.buttons&&game.buttons.some(b=>b.who==='server')?game.buttons.filter(b=>b.who==='server'):[{label:'+1',pts:1},{label:'+2',pts:2},{label:'+3',pts:3}]).map((b,i)=><button key={i} type="button" className={'srBtn '+(b.pts<0?'ghost':'good')} onClick={()=>addSrv(b.pts)}>{b.label}</button>)}</div>
          </div>
          <div className="srSide">
            <h4>Returner</h4>
            <div className="srNum" style={{color:'#86efac'}}>{ret}</div>
            <div className="srBtnRow">{(game&&game.buttons&&game.buttons.some(b=>b.who==='returner')?game.buttons.filter(b=>b.who==='returner'):[{label:'+1',pts:1},{label:'+2',pts:2},{label:'+3',pts:3}]).map((b,i)=><button key={i} type="button" className={'srBtn '+(b.pts<0?'ghost':'good')} onClick={()=>addRet(b.pts)}>{b.label}</button>)}</div>
          </div>
        </div>
        <div className="srBtnRow" style={{marginTop:'10px'}}>
          <button type="button" className="srBtn ghost" onClick={doUndo} disabled={!undo.length}>Undo</button>
          <button type="button" className="srBtn ghost" onClick={resetScore}>Reset score</button>
          <button type="button" className="srBtn" onClick={pushPlayerView}>Push to Player View</button>
          <button type="button" className="srBtn ghost" onClick={openPlayerView}>Open Player View</button>
          {setSession&&<button type="button" className="srBtn" onClick={addToSession}>Add to Session</button>}
        </div>
      </div>}

      <CollapsibleLayer num="1" title="Game Logic" subtitle="What counts and how the exchange runs" color="green" defaultOpen={false}>
        <p>{game?game.task+' ':''}Run live from a real serve. Options: must attack the third ball, must finish with a volley, blind serve pattern, or a fixed serve sequence. A shot counts only if it does its job in the phase (create, neutralise or exploit).</p>
      </CollapsibleLayer>
      <CollapsibleLayer num="2" title="Constraints" subtitle="Shape behaviour without changing the rules" color="blue" defaultOpen={false}>
        <p><strong>Tactical:</strong> return to the T · force the weak side · attack width. <strong>Technical:</strong> Second Eye · Quiet Eye · hold finish · racquet above wrist. <strong>Mental:</strong> stay calm under serve pressure · fox (deception) · shark (attack mode). Layer one at a time so the serve or return shape is forced by the constraint, not coached by instruction.</p>
      </CollapsibleLayer>
      <CollapsibleLayer num="3" title="Scoring Logic" subtitle="Reward the function" color="gold" defaultOpen={false}>
        <p>{game?(game.scoring+(game.bonus?(' Bonus: '+game.bonus):'')):''} Optional overlays: serve winner +2 · weak return forced +1 · third-ball winner +3. Award on outcome, not aesthetics.</p>
      </CollapsibleLayer>
      <CollapsibleLayer num="4" title="DB Handicap" subtitle="Skill leveller" color="purple" defaultOpen={false}>
        <p className="srMuted">Use Double Bounce as the leveller so server and returner can compete on equal terms.</p>
        <div className="srObj" style={{marginTop:'8px'}}>
          <label className="srObjBox"><div className="lbl">Server DB</div><select value={srvDb} onChange={e=>setSrvDb(e.target.value)} style={{width:'100%',background:'#0b1118',color:'#eaf4fb',border:'1px solid #2c3c4e',borderRadius:'8px',padding:'8px'}}>{['Unlimited','1 bounce','2 bounce','3 bounce'].map(o=><option key={o}>{o}</option>)}</select></label>
          <label className="srObjBox"><div className="lbl">Returner DB</div><select value={retDb} onChange={e=>setRetDb(e.target.value)} style={{width:'100%',background:'#0b1118',color:'#eaf4fb',border:'1px solid #2c3c4e',borderRadius:'8px',padding:'8px'}}>{['Unlimited','1 bounce','2 bounce','3 bounce'].map(o=><option key={o}>{o}</option>)}</select></label>
        </div>
      </CollapsibleLayer>
    </div>
  </div>;
}

function ServeReturnPlayerDisplay({payload={}}){
  const g=payload.game||{};
  return <div className="srDisp">
    <SRStyles/>
    <div className="srDispTop"><span>SERVE &amp; RETURN™ · {payload.tabLabel||''}</span><h1>{g.title||'Serve & Return'}</h1></div>
    {payload.showPhase&&<div style={{textAlign:'center',marginBottom:'2.5vh'}}><span className="srPhase" style={{fontSize:'1.3rem',padding:'8px 20px'}}>Phase · {payload.phase}</span></div>}
    <div className="srDispObj">
      <div className="srDispCard"><div className="l">Objective</div><div className="t">{g.task||''}</div></div>
      <div className="srDispCard"><div className="l">How to score</div><div className="t">{g.scoring||''}</div></div>
    </div>
    <div className="srDispScore">
      <div className="s"><div className="n">{payload.serverPts||0}</div><div className="who">Server</div></div>
      <div className="s"><div className="n" style={{color:'#86efac'}}>{payload.returnerPts||0}</div><div className="who">Returner</div></div>
    </div>
    {g.bonus&&<div className="srDispBonus">Bonus available: {g.bonus}</div>}
  </div>;
}

/* ───────────────────────── BUCKET LOB™ ───────────────────────── */
function LobStyles(){return <style>{`
.lobWrap{max-width:1000px;margin:0 auto;}
.lobBoard{display:flex;gap:14px;flex-wrap:wrap;margin:14px 0;}
.lobMain{flex:2;min-width:280px;background:#0b1320;border:1px solid #213247;border-radius:14px;padding:16px;}
.lobSide{flex:1;min-width:220px;background:#0f1822;border:1px solid #223044;border-radius:14px;padding:16px;}
.lobLearner{font-size:1.4rem;font-weight:800;color:#ffd479;}
.lobBig{font-size:3rem;font-weight:800;line-height:1;color:#86efac;}
.lobAtt{font-size:1rem;color:#7c8ea0;margin-top:4px;}
.lobBtnRow{display:flex;gap:8px;flex-wrap:wrap;margin-top:12px;}
.lobBtn{border-radius:10px;padding:11px 15px;font-weight:700;cursor:pointer;border:1px solid #2c3c4e;background:#16466a;color:#eaf4fb;}
.lobBtn.bucket{background:#114d2c;border-color:#1d6b3f;color:#bff0d0;font-size:1.05rem;}
.lobBtn.block{background:#2a0d12;border-color:#7a2233;color:#fca5b5;}
.lobBtn.ghost{background:#0b1118;border-color:#2c3c4e;color:#9fb0c2;}
.lobRow{display:flex;justify-content:space-between;align-items:center;padding:7px 10px;border-radius:8px;background:#0d1722;margin-bottom:6px;}
.lobRow.on{background:#14331f;border:1px solid #1d6b3f;}
.lobRow b{color:#eaf4fb;}
.lobMuted{color:#7c8ea0;font-size:0.85rem;line-height:1.5;}
.lobChips{display:flex;gap:8px;flex-wrap:wrap;margin-top:8px;}
.lobChip{background:#15233a;border:1px solid #294063;color:#9cc4ec;border-radius:999px;padding:4px 11px;font-size:0.8rem;font-weight:700;}
/* player display */
.lobDisp{min-height:100vh;background:radial-gradient(circle at 50% 0%,#11331f,#060c14 70%);color:#eaf4fb;padding:5vh 4vw;box-sizing:border-box;text-align:center;}
.lobDisp h1{font-size:3rem;margin:6px 0;}
.lobDisp .obj{font-size:1.7rem;color:#bff0d0;max-width:800px;margin:0 auto 3vh;line-height:1.4;}
.lobDispScore{font-size:6rem;font-weight:800;color:#86efac;line-height:1;}
.lobDispAtt{font-size:1.4rem;color:#9fb0c2;margin-top:6px;}
.lobLead{max-width:560px;margin:3vh auto 0;}
.lobLead .r{display:flex;justify-content:space-between;background:#0f1d30;border:1px solid #21384e;border-radius:10px;padding:10px 16px;margin-bottom:7px;font-size:1.2rem;}
`}</style>;}

function LobModule({setScreen,setSession,embedded=false}){
  const [count,setCount]=useState(7);
  const [names,setNames]=useState(['P1','P2','P3','P4','P5','P6','P7']);
  const [rot,setRot]=useState(0);
  const [attempts,setAttempts]=useState(0);
  const [scores,setScores]=useState({});
  const [side,setSide]=useState('right');
  const [undo,setUndo]=useState([]);
  const [projecting,setProjecting]=useState(()=>!!getCourtModeFromUrl());
  const TARGET=20;

  const roster=names.slice(0,count);
  const shortLine=Math.max(0,count-4); // standing guards on the short line
  // role cycle (anticlockwise): 0 Learner · 1..shortLine Short line · then Bucket sit · Collector · Feeder
  function playerAtPos(p){return roster[(((p-rot)%count)+count)%count];}
  const learnerName=playerAtPos(0);
  const shortLineNames=Array.from({length:shortLine},(_,i)=>playerAtPos(1+i));
  const bucketSitName=playerAtPos(shortLine+1);
  const collectorName=playerAtPos(shortLine+2);
  const feederName=playerAtPos(shortLine+3);
  const curName=learnerName;
  const curScore=scores[curName]||0;
  const done=attempts>=TARGET;

  function pushUndo(){setUndo(p=>[...p.slice(-29),{attempts,scores:{...scores},rot,side}]);}
  function record(pts){if(done)return;pushUndo();setScores(s=>({...s,[curName]:(s[curName]||0)+pts}));setAttempts(a=>a+1);}
  function doUndo(){setUndo(p=>{if(!p.length)return p;const s=p[p.length-1];setAttempts(s.attempts);setScores(s.scores);setRot(s.rot);setSide(s.side);return p.slice(0,-1);});}
  function rotate(){pushUndo();setRot(r=>(r+1)%count);setAttempts(0);} // everyone moves one spot anticlockwise
  function flipSide(){pushUndo();setSide(s=>s==='right'?'left':'right');setAttempts(0);}

  const leaderboard=roster.map(n=>({name:n,score:scores[n]||0})).sort((a,b)=>b.score-a.score);
  const objective='Play a high cross-court lob over the short-line guards so it drops into the back-corner bucket.';

  useEffect(()=>{
    if(!projecting)return;
    writeLivePlayerRoom(getPersistentLiveRoomId(),'bucketlob',{type:'bucketlob',learner:curName,feeder:feederName,score:curScore,attemptsLeft:TARGET-attempts,side,objective,leaderboard});
  },[projecting,rot,attempts,scores,side]);

  function pushPV(){setProjecting(true);writeLivePlayerRoom(getPersistentLiveRoomId(),'bucketlob',{type:'bucketlob',learner:curName,feeder:feederName,score:curScore,attemptsLeft:TARGET-attempts,side,objective,leaderboard});}
  function openPV(){try{window.open(buildLivePlayerViewUrl(),'_blank');}catch{}}

  function addToSession(){
    if(!setSession)return;
    setSession(prev=>appendToSessionState(prev,{id:Date.now()+Math.random(),title:'Bucket Lob — high cross lob',category:'Shots',format:'4–7 players · one court',duration:15,task:objective+' Feeder drops medium-high to the side; standing guards hold the short line (positioned by height) and a seated guard sits in front of the bucket; a collector feeds the feeder. Guards are fixed — racquet only.',scoring:'5 points if the ball lands in the bucket, −1 for every guard interception. 20 lobs each, then rotate anticlockwise; repeat on the opposite side.',rationale:'No technical instruction. The standing short-line guards (height-set) force the lob shape — high enough to clear them, deep enough to die in the bucket — a representative copy of lobbing over an opponent’s volley into the back corner. The bucket guard sits so the target stays reachable.',coach:'Analogy not instruction: scoop sand with a spade and throw it back over your non-playing shoulder. Raise or lower the standing guards to demand a higher or flatter trajectory.',playerFocus:'Clear the wall, drop in the bucket.',layers:[],rld:4}));
  }

  return <div className={embedded?'':'page'}>
    <LobStyles/>
    {!embedded&&<div className="pageTop"><div><h1>Bucket Lob™</h1><p className="mutedText">Learn the lob with no technical instruction — the guard wall shapes the shot</p></div><button className="secondaryBtn" onClick={()=>setScreen&&setScreen('home')}>Home</button></div>}
    <div className="lobWrap">
      <CoachRationale label="Why this works — constraint, not instruction">
        <p>Nobody is told how to swing. The <strong>guard wall sets the problem</strong>: a line of players along the service box, each raising the racquet to their own height, is the barrier the ball must clear; the <strong>bucket in the back corner</strong> is where it must die. The only lob that scores is one that goes <em>up enough to clear the guards and back enough to drop in the bucket</em> — which is exactly the shape of a real defensive lob over an opponent’s volley. Set guard height to demand the trajectory you want: taller/racquets-up forces a higher lob, lower guards allow a flatter one.</p>
        <p className="lobMuted">Coaching analogy (not a technical cue): scoop a spade of sand off the beach and throw it back over your non-playing shoulder.</p>
      </CoachRationale>

      <div className="lobChips">
        <span className="lobChip">Players: {count}</span>
        <span className="lobChip">Short-line guards: {shortLine}</span>
        <span className="lobChip">Feed side: {side==='right'?'Right [7]':'Left'}</span>
        <span className="lobChip">Bucket: back corner [8]</span>
      </div>
      <div className="lobChips" style={{marginTop:'4px'}}>
        <span className="lobChip" style={{background:'#3a2f10',borderColor:'#7a6322',color:'#ffd479'}}>🎯 Learner: {learnerName}</span>
        {shortLineNames.length>0&&<span className="lobChip">🧱 Short line: {shortLineNames.join(' · ')}</span>}
        <span className="lobChip">🪑 Bucket (sitting): {bucketSitName}</span>
        <span className="lobChip">🧺 Collector: {collectorName}</span>
        <span className="lobChip">🎾 Feeder: {feederName}</span>
      </div>
      <div className="lobBtnRow">
        <span className="lobMuted" style={{alignSelf:'center'}}>Court size:</span>
        {[4,5,6,7].map(c=><button key={c} type="button" className={'lobBtn ghost'+(count===c?' bucket':'')} onClick={()=>setCount(c)}>{c}</button>)}
      </div>

      <div className="lobBoard">
        <div className="lobMain">
          <div className="lobLearner">Learner: {curName}</div>
          <div className="lobBig">{curScore}</div>
          <div className="lobAtt">{done?'20 lobs complete — rotate':('Lob '+(attempts+1)+' of '+TARGET)}</div>
          <div className="lobBtnRow">
            <button type="button" className="lobBtn bucket" onClick={()=>record(5)} disabled={done}>In bucket +5</button>
            <button type="button" className="lobBtn block" onClick={()=>record(-1)} disabled={done}>Guard intercept −1</button>
            <button type="button" className="lobBtn ghost" onClick={()=>record(0)} disabled={done}>Short / out (0)</button>
          </div>
          <div className="lobBtnRow">
            <button type="button" className="lobBtn ghost" onClick={doUndo} disabled={!undo.length}>Undo</button>
            <button type="button" className="lobBtn" onClick={rotate}>Rotate (anticlockwise) →</button>
            <button type="button" className="lobBtn ghost" onClick={flipSide}>Switch to {side==='right'?'left':'right'} side</button>
          </div>
          <div className="lobBtnRow">
            <button type="button" className="lobBtn" onClick={pushPV}>Push to Player View</button>
            <button type="button" className="lobBtn ghost" onClick={openPV}>Open Player View</button>
            {setSession&&<button type="button" className="lobBtn" onClick={addToSession}>Add to Session</button>}
          </div>
        </div>
        <div className="lobSide">
          <h4 style={{margin:'0 0 8px',color:'#eaf4fb'}}>Scoreboard</h4>
          {leaderboard.map((p,i)=><div key={p.name} className={'lobRow'+(p.name===curName?' on':'')}><b>{i===0&&p.score>0?'👑 ':''}{p.name}</b><span>{p.score}</span></div>)}
          <p className="lobMuted" style={{marginTop:'10px'}}>Feeder drops medium-high to the {side} side. {shortLine} guard{shortLine===1?'':'s'} stand on the short line; the bucket guard <strong>sits</strong> in front of the bucket — if they stand, scoring is impossible. Guards are fixed (racquet only, no moving). One player collects balls for the feeder. After 20 lobs everyone rotates one spot anticlockwise.</p>
        </div>
      </div>

      <CollapsibleLayer num="1" title="Game Logic" subtitle="How it runs" color="green" defaultOpen={false}>
        <p>The feeder plays a medium-high drop to the {side} side. The learner plays one high cross-court lob aiming for the back-corner bucket. Standing guards hold the short line and may not move (racquet only); the bucket guard <strong>sits</strong> in front of the bucket so the ball can still drop in. Each learner gets 20 lobs, then everyone rotates one spot anticlockwise — learner to the short line, short line on to the bucket seat, bucket guard to collecting, collector to feeding, feeder becomes the new learner. Repeat on the opposite side.</p>
      </CollapsibleLayer>
      <CollapsibleLayer num="2" title="Constraints" subtitle="The guard wall shapes the shot" color="blue" defaultOpen={false}>
        <p>Position and restrict the <strong>standing short-line guards by height</strong> so a successful lob has the trajectory you want — racquets up raises the barrier and demands a higher lob; lower or spread guards change the window. The <strong>bucket guard must sit</strong>: a standing guard there makes the bucket unreachable, so seating them is what keeps the target live. Guards are fixed — they cannot move, only reach. The lob shape is forced by the barrier, not by a coaching cue.</p>
      </CollapsibleLayer>
      <CollapsibleLayer num="3" title="Scoring Logic" subtitle="Fully observable" color="gold" defaultOpen={false}>
        <p><strong>+5</strong> if the ball lands in the bucket. <strong>−1</strong> for every guard interception. Short or out = 0. No coach judgement required — the bucket and the guards decide. 20 lobs each; highest total after both sides wins.</p>
      </CollapsibleLayer>
      <CollapsibleLayer num="4" title="DB Handicap" subtitle="Skill leveller" color="purple" defaultOpen={false}>
        <p className="lobMuted">Level the field by handicapping stronger players: fewer attempts, a smaller bucket, an extra guard, or a higher guard wall on their turn. Keep the challenge point near 70% success for everyone.</p>
      </CollapsibleLayer>
    </div>
  </div>;
}

function LobPlayerDisplay({payload={}}){
  const lb=payload.leaderboard||[];
  return <div className="lobDisp">
    <LobStyles/>
    <div style={{letterSpacing:'0.14em',color:'#7fc8a0'}}>BUCKET LOB™</div>
    <h1>{payload.learner||'Learner'}</h1>
    <div className="obj">{payload.objective||''}</div>
    <div className="lobDispScore">{payload.score||0}</div>
    <div className="lobDispAtt">{payload.attemptsLeft} lobs left · {payload.side==='right'?'right':'left'} side</div>
    {lb.length>0&&<div className="lobLead">{lb.map((p,i)=><div className="r" key={p.name}><span>{i===0&&p.score>0?'👑 ':''}{p.name}</span><span>{p.score}</span></div>)}</div>}
  </div>;
}

/* ───────────────────── COURT MONITOR (King of Courts) ───────────────────── */
function cmOrdinal(n){const s=['th','st','nd','rd'],v=n%100;return n+(s[(v-20)%10]||s[v]||s[0]);}

function normalizeCourtPayload(row){
  if(!row||!row.payload)return null;
  const p=row.payload,t=p.type;
  const ageMs=row.updated_at?(Date.now()-new Date(row.updated_at).getTime()):(p.updatedAt?Date.now()-p.updatedAt:null);
  const stale=ageMs!=null&&ageMs>20000;
  let game='Live',headline='',target=null,pct=null,leaderName='',winnerName=p.winnerName||null,players=[];
  if(t==='snakesladders'){
    game='Snakes & Ladders';players=(p.players||[]).map(x=>({name:x.name,score:x.pos}));
    const lead=players.reduce((a,b)=>(!a||b.score>a.score)?b:a,null);
    leaderName=lead?lead.name:'';target=p.size||50;headline=lead?('Square '+lead.score):'';pct=lead&&target?lead.score/target:null;
    if(p.winnerName){pct=1;headline='Winner: '+p.winnerName;}
  }else if(t==='tinwar'){
    game='Tin War';const ladder=p.ladder||[];const max=Math.max(1,ladder.length-1);
    players=(p.players||[]).map(x=>({name:x.name,score:max-(x.peak??x.idx??max)}));
    const lead=(p.players||[]).reduce((a,b)=>{const ai=a?(a.peak??a.idx??max):99;const bi=(b.peak??b.idx??max);return bi<ai?b:a;},null);
    const li=lead?(lead.peak??lead.idx??max):max;leaderName=lead?lead.name:'';headline=ladder[li]?ladder[li].label:'';target='HIGH';pct=(max-li)/max;
  }else if(t==='disruption'&&p.battle){
    game='Court Battle';const cs=p.battle.courts||[];const best=cs.reduce((m,c)=>Math.max(m,c.best||0),0);
    headline=best+' streak';target=p.battle.target;pct=p.battle.target?best/p.battle.target:null;
  }else if(t==='servereturn'){game='Serve & Return';headline='S '+(p.serverPts||0)+' · R '+(p.returnerPts||0);}
  else if(t==='bucketlob'){game='Bucket Lob';leaderName=p.learner||'';headline=(p.score||0)+' pts';}
  else if(t==='pattern'){game='Pattern Lab';headline=p.title||'Pattern';pct=null;}
  else if(t==='doublebounce'){game='Double Bounce';}
  else if(t==='blindtarget'){game='Poker';players=(p.players||[]).map(x=>({name:x.name,score:x.score}));leaderName=p.leaderName||'';headline=p.winnerName?('🏆 '+p.winnerName):(p.started?((p.leaderScore||0)+' pts'):'Ready');winnerName=p.winnerName||null;pct=null;}
  return {type:t,game,headline,target,pct:pct!=null?Math.max(0,Math.min(1,pct)):null,leaderName,winnerName,players,stale,ageMs};
}

function CMStyles(){return <style>{`
.cmWrap{max-width:1100px;margin:0 auto;}
.cmHero{background:linear-gradient(135deg,#0d2a18,#0b1320);border:1px solid #1d6b3f;border-radius:16px;padding:18px 20px;margin-bottom:16px;text-align:center;}
.cmHero .k{letter-spacing:0.14em;color:#7fc8a0;font-size:0.9rem;}
.cmHero h2{margin:6px 0 2px;color:#eaf4fb;font-size:1.8rem;}
.cmHero .lead{font-size:1.3rem;color:#ffd479;font-weight:800;margin-top:6px;}
.cmRow{display:flex;gap:10px;flex-wrap:wrap;align-items:center;margin-bottom:14px;}
.cmGrid{display:grid;grid-template-columns:repeat(auto-fill,minmax(260px,1fr));gap:12px;}
.cmCard{background:#0f1822;border:1px solid #223044;border-radius:14px;padding:15px;}
.cmCard.lead{border-color:#1d6b3f;background:#0d2417;}
.cmCard.stale{opacity:0.5;}
.cmCard .cnum{font-size:1.1rem;font-weight:800;color:#9cc4ec;}
.cmCard .game{font-size:0.8rem;color:#6b8299;margin-top:2px;}
.cmCard .head{font-size:2rem;font-weight:800;color:#eaf4fb;margin:8px 0 2px;}
.cmCard .who{font-size:0.9rem;color:#86efac;}
.cmBar{height:10px;border-radius:6px;background:#1a2740;overflow:hidden;margin-top:10px;}
.cmBar i{display:block;height:100%;background:linear-gradient(90deg,#2f9bff,#34e07a);}
.cmRank{display:inline-block;background:#15233a;border:1px solid #294063;color:#9cc4ec;border-radius:999px;padding:2px 10px;font-weight:800;font-size:0.8rem;}
.cmWait{color:#6b8299;font-style:italic;margin-top:8px;}
.cmLink{display:flex;gap:8px;align-items:center;margin-top:10px;}
.cmLinkBtn{background:#16466a;border:1px solid #2E6E8E;color:#eaf4fb;border-radius:8px;padding:7px 11px;font-weight:700;cursor:pointer;font-size:0.85rem;}
.cmShareCard{background:#0b1320;border:1px dashed #2c4a6e;border-radius:12px;padding:12px 14px;margin-bottom:8px;}
.cmShareCard .ct{font-weight:800;color:#9cc4ec;}
.cmShareCard code{display:block;color:#7c8ea0;font-size:0.72rem;word-break:break-all;margin-top:4px;}
.cmCourtBanner{position:sticky;top:0;left:0;right:0;z-index:9000;background:linear-gradient(90deg,#0d2a18,#102338);border-bottom:2px solid #1d6b3f;color:#eaf4fb;padding:9px 14px;text-align:center;font-weight:800;letter-spacing:0.03em;font-size:1.05rem;}
`}</style>;}

function CourtMonitor({setScreen}){
  const base=useMemo(()=>{const cm=getCourtModeFromUrl();return cm?cm.host:getPersistentLiveRoomId();},[]);
  const [count,setCount]=useState(()=>{try{return Number(localStorage.getItem('cbCourtCount'))||3;}catch{return 3;}});
  const [rooms,setRooms]=useState({});
  const [copied,setCopied]=useState(null);
  const [showLinks,setShowLinks]=useState(true);
  useEffect(()=>{try{localStorage.setItem('cbCourtCount',String(count));}catch{}},[count]);

  useEffect(()=>{
    let cancelled=false;
    async function load(){
      const ns=Array.from({length:count},(_,i)=>i+1);
      const out={};
      await Promise.all(ns.map(async n=>{const row=await readLivePlayerRoom(courtRoomId(base,n));out[n]=normalizeCourtPayload(row);}));
      if(cancelled)return;
      setRooms(out);
      const ranking=ns.map(n=>({court:n,pct:out[n]?out[n].pct:null,headline:out[n]?out[n].headline:'',leaderName:out[n]?out[n].leaderName:'',game:out[n]?out[n].game:null})).filter(r=>r.game).sort((a,b)=>((b.pct)||0)-((a.pct)||0));
      writeLivePlayerRoom(courtStandingsRoomId(base),'standings',{type:'standings',count,ranking,updatedAt:Date.now()});
    }
    load();const id=setInterval(load,2500);
    return ()=>{cancelled=true;clearInterval(id);};
  },[base,count]);

  const ranked=Array.from({length:count},(_,i)=>i+1).map(n=>({n,d:rooms[n]})).sort((a,b)=>{const ap=a.d?.pct,bp=b.d?.pct;if(ap==null&&bp==null)return a.n-b.n;if(ap==null)return 1;if(bp==null)return -1;return bp-ap;});
  const liveCourts=ranked.filter(r=>r.d&&r.d.game&&!r.d.stale);
  const leader=liveCourts.length?ranked.find(r=>r.d&&r.d.game):null;
  function copyLink(n){try{navigator.clipboard.writeText(buildCourtLink(n,base));setCopied(n);setTimeout(()=>setCopied(null),1500);}catch{}}

  return <div className="page">
    <CMStyles/>
    <div className="pageTop"><div><h1>Court Monitor</h1><p className="mutedText">King of Courts — every court, one live leaderboard</p></div><button className="secondaryBtn" onClick={()=>setScreen&&setScreen('home')}>Home</button></div>
    <div className="cmWrap">
      <div className="cmHero">
        <div className="k">KING OF COURTS</div>
        <h2>{liveCourts.length} of {count} courts live</h2>
        {leader&&leader.d&&leader.d.pct!=null?<div className="lead">👑 Court {leader.n} leading — {leader.d.headline}{leader.d.leaderName?(' ('+leader.d.leaderName+')'):''}</div>:<div className="cmWait">Waiting for courts to report…</div>}
      </div>

      <div className="cmRow">
        <span className="mutedText">Courts:</span>
        {[2,3,4,5,6].map(c=><button key={c} type="button" className={'lobBtn ghost'+(count===c?' bucket':'')} onClick={()=>setCount(c)} style={{borderRadius:'9px',padding:'8px 13px',fontWeight:700,cursor:'pointer',border:count===c?'1px solid #1d6b3f':'1px solid #2c3c4e',background:count===c?'#114d2c':'#0b1118',color:count===c?'#bff0d0':'#9fb0c2'}}>{c}</button>)}
        <button type="button" className="cmLinkBtn" onClick={()=>setShowLinks(s=>!s)} style={{marginLeft:'auto'}}>{showLinks?'Hide':'Show'} court links</button>
      </div>

      {showLinks&&<div style={{marginBottom:'16px'}}>
        <p className="mutedText" style={{marginTop:0}}>Send each court its own link. Open it on that court's device (phone or tablet), run any game, and it reports here automatically.</p>
        {Array.from({length:count},(_,i)=>i+1).map(n=><div className="cmShareCard" key={n}>
          <div style={{display:'flex',justifyContent:'space-between',alignItems:'center'}}><span className="ct">Court {n}</span><button type="button" className="cmLinkBtn" onClick={()=>copyLink(n)}>{copied===n?'Copied ✓':'Copy link'}</button></div>
          <code>{buildCourtLink(n,base)}</code>
        </div>)}
      </div>}

      <div className="cmGrid">
        {ranked.map(({n,d},i)=>{
          const isLead=d&&d.game&&d.pct!=null&&i===0;
          return <div key={n} className={'cmCard'+(isLead?' lead':'')+(d&&d.stale?' stale':'')}>
            <div style={{display:'flex',justifyContent:'space-between',alignItems:'baseline'}}>
              <span className="cnum">{isLead?'👑 ':''}Court {n}</span>
              {d&&d.game&&d.pct!=null&&<span className="cmRank">{cmOrdinal(i+1)}</span>}
            </div>
            {d&&d.game?<>
              <div className="game">{d.game}{d.stale?' · paused':''}</div>
              <div className="head">{d.headline||'—'}</div>
              {d.leaderName&&<div className="who">{d.leaderName}</div>}
              {d.pct!=null&&<div className="cmBar"><i style={{width:Math.round(d.pct*100)+'%'}}/></div>}
            </>:<div className="cmWait">No device connected yet</div>}
          </div>;
        })}
      </div>
    </div>
  </div>;
}

function CourtStandingBanner({host,court}){
  const [rank,setRank]=useState(null),[total,setTotal]=useState(0),[leadCourt,setLeadCourt]=useState(null);
  useEffect(()=>{
    let c=false;
    async function load(){const row=await readLivePlayerRoom(courtStandingsRoomId(host));if(c||!row||!row.payload)return;const r=row.payload.ranking||[];const idx=r.findIndex(x=>x.court===court);setRank(idx>=0?idx+1:null);setTotal(r.length);setLeadCourt(r[0]?r[0].court:null);}
    load();const id=setInterval(load,3000);return ()=>{c=true;clearInterval(id);};
  },[host,court]);
  return <div className="cmCourtBanner">
    <CMStyles/>
    COURT {court}{rank?(' · '+cmOrdinal(rank)+' of '+total):''}{leadCourt?(leadCourt===court?' · 👑 leading!':(' · leader: Court '+leadCourt)):''}
  </div>;
}

function App(){
const[liveRoomParam]=useState(()=>getLiveRoomFromUrl());
const[livePayload,setLivePayload]=useState(null);
const[liveStatus,setLiveStatus]=useState(liveRoomParam?'Connecting live display…':'');
const[sharedPlayerPayload]=useState(()=>decodePlayerPayloadFromUrl());
const[sharedPlayerGame]=useState(()=>sharedPlayerPayload?.type==='game'?normaliseGameCard(sharedPlayerPayload.game):decodePlayerGameFromUrl());
const[sharedPlayerCompetition]=useState(()=>sharedPlayerPayload?.type==='competition'?(sharedPlayerPayload.competition||sharedPlayerPayload):decodePlayerCompetitionFromUrl());
const liveCompetition=livePayload?.type==='competition'?(livePayload.competition||livePayload):((livePayload?.mode&&['matchplay','roundRobin','monrad','invasion','nsl'].includes(livePayload.mode))?livePayload:null);
const liveGame=livePayload?.type==='game'?normaliseGameCard(livePayload.game):null;
const initialPlayerDisplay=!!liveRoomParam||!!sharedPlayerGame||!!sharedPlayerCompetition;
const[screen,setScreen]=useState(()=>initialPlayerDisplay?'playerDisplay':'home');
useEffect(()=>{
  if(!liveRoomParam) return;
  let cancelled=false;
  async function load(){
    const row=await readLivePlayerRoom(liveRoomParam);
    if(cancelled) return;
    if(row?.payload){setLivePayload(row.payload);setLiveStatus('Live');}
    else setLiveStatus('Waiting for coach device…');
  }
  load();
  const id=setInterval(load,2000);
  return ()=>{cancelled=true;clearInterval(id);};
},[liveRoomParam]);
const[backStack,setBackStack]=useState([]);
const courtMode=useMemo(()=>getCourtModeFromUrl(),[]);
const[searchOpen,setSearchOpen]=useState(false);
const[searchQ,setSearchQ]=useState('');
const searchAll=useMemo(()=>buildSearchIndex(),[]);
const searchResults=useMemo(()=>{const q=searchQ.trim().toLowerCase();if(!q)return searchAll.slice(0,40);const tokens=q.split(/\s+/).filter(Boolean);return searchAll.filter(it=>{const hay=(it.label+' '+(it.sub||'')+' '+(it.kw||'')).toLowerCase();return tokens.every(t=>hay.includes(t));}).slice(0,80);},[searchQ,searchAll]);
function go(next){
  if(!next||next===screen) return;
  setBackStack(prev=>[...prev,screen].slice(-30));
  setScreen(next);
}
function runSearch(item){
  setSearchOpen(false);setSearchQ('');
  if(item.classId){try{localStorage.setItem(GAME_LIBRARY_CLASS_KEY,item.classId);}catch{}}
  const target=item.screen||'home';
  if(target===screen){if(item.classId){setBackStack(prev=>[...prev,screen].slice(-30));setScreen('home');setTimeout(()=>setScreen('games'),0);}return;}
  go(target);
}
function goBack(){
  setBackStack(prev=>{
    const last=prev.length?prev[prev.length-1]:'home';
    setScreen(last);
    return prev.slice(0,-1);
  });
}
const[players,setPlayers]=useState(()=>{try{return JSON.parse(localStorage.getItem(PLAYER_KEY))||[]}catch{return[]}});
const[session,setSession]=useState(()=>{try{const s=JSON.parse(localStorage.getItem(SESSION_KEY));return Array.isArray(s)?s:(s&&Array.isArray(s.rotations)?s.rotations:[]);}catch{return[]}});
const[lastInvasionFormat,setLastInvasionFormat]=useState(()=>{
  try{
    const direct=localStorage.getItem('checkerboardInvasionFormat');
    if(direct==='points'||direct==='lives') return direct;
    const saved=JSON.parse(localStorage.getItem('checkerboardCompetitionProjection')||'{}');
    if(saved.invasionFormat==='points'||saved.invasionFormat==='lives') return saved.invasionFormat;
  }catch{}
  return 'lives';
});
useEffect(()=>{localStorage.setItem(PLAYER_KEY,JSON.stringify(players));},[players]);
useEffect(()=>{localStorage.setItem(SESSION_KEY,JSON.stringify(session));},[session]);
useEffect(()=>{try{localStorage.setItem('checkerboardInvasionFormat',lastInvasionFormat);}catch{}},[lastInvasionFormat]);
if(screen==='playerDisplay'&&liveRoomParam&&!livePayload){return <div className="playerDisplayPage"><div className="playerDisplayShell competitionPlayerDisplayShell"><div className="playerDisplayTop"><span>LIVE PLAYER DISPLAY</span><h1>Checkerboard Live</h1><p>{liveStatus}</p></div></div></div>;}
if(screen==='playerDisplay'&&livePayload?.type==='snakesladders'){return <SnakesLaddersPlayerDisplay payload={livePayload}/>;}
if(screen==='playerDisplay'&&livePayload?.type==='doublebounce'){return <DoubleBounceSuitePlayerDisplay payload={livePayload}/>;}
if(screen==='playerDisplay'&&livePayload?.type==='tinwar'){return <TinWarPlayerDisplay payload={livePayload}/>;}
if(screen==='playerDisplay'&&livePayload?.type==='disruption'){return <DisruptionPlayerDisplay payload={livePayload}/>;}
if(screen==='playerDisplay'&&livePayload?.type==='servereturn'){return <ServeReturnPlayerDisplay payload={livePayload}/>;}
if(screen==='playerDisplay'&&livePayload?.type==='bucketlob'){return <LobPlayerDisplay payload={livePayload}/>;}
if(screen==='playerDisplay'&&livePayload?.type==='pattern'){return <PatternLabPlayerDisplay payload={livePayload}/>;}
if(screen==='playerDisplay'&&liveCompetition){return <CompetitionPlayerDisplayView competition={liveCompetition} setScreen={go}/>;}
if(screen==='playerDisplay'&&liveGame){return <PlayerDisplayView session={session} setScreen={go} sharedGame={liveGame}/>;}
if(screen==='playerDisplay'&&sharedPlayerCompetition){return <CompetitionPlayerDisplayView competition={sharedPlayerCompetition} setScreen={go}/>;}
if(screen==='playerDisplay'&&sharedPlayerGame){return <PlayerDisplayView session={session} setScreen={go} sharedGame={sharedPlayerGame}/>;}
return <div>
<div className="versionStamp" title="Deployed build">{APP_VERSION}</div>
{searchOpen&&<div onClick={()=>setSearchOpen(false)} style={{position:'fixed',inset:0,zIndex:10000,background:'rgba(2,6,12,0.6)',backdropFilter:'blur(2px)'}}>
  <div onClick={e=>e.stopPropagation()} style={{maxWidth:'620px',margin:'60px auto 0',width:'92%',background:'#0d1722',border:'1px solid #243140',borderRadius:'16px',padding:'14px',boxShadow:'0 20px 60px rgba(0,0,0,0.6)',maxHeight:'82vh',display:'flex',flexDirection:'column'}}>
    <div style={{display:'flex',gap:'8px',alignItems:'center'}}>
      <input autoFocus value={searchQ} onChange={e=>setSearchQ(e.target.value)} placeholder="Search games, modules, tools…" style={{flex:1,background:'#0b1118',border:'1px solid #2c3c4e',borderRadius:'10px',color:'#eaf4fb',fontSize:'1rem',padding:'12px 14px',outline:'none'}}/>
      <button onClick={()=>setSearchOpen(false)} style={{background:'#16466a',border:'1px solid #2E6E8E',color:'#eaf4fb',borderRadius:'10px',padding:'12px 14px',fontWeight:700,cursor:'pointer'}}>Close</button>
    </div>
    <div style={{marginTop:'10px',overflowY:'auto'}}>
      {searchResults.length===0&&<div style={{color:'#7c8ea0',padding:'18px',textAlign:'center'}}>No matches for "{searchQ}"</div>}
      {searchResults.map((r,i)=><button key={i} onClick={()=>runSearch(r)} style={{display:'flex',flexDirection:'column',alignItems:'flex-start',gap:'2px',width:'100%',textAlign:'left',background:'#0f1822',border:'1px solid #1e2c3c',borderRadius:'10px',padding:'11px 14px',marginBottom:'7px',cursor:'pointer'}}>
        <span style={{fontWeight:700,color:'#eaf4fb'}}>{r.label}</span>
        <span style={{color:'#6b8299',fontSize:'0.8rem'}}>{r.sub}</span>
      </button>)}
    </div>
  </div>
</div>}
{screen!=='home'&&screen!=='sessions'&&screen!=='playerDisplay'&&<button onClick={()=>go('sessions')} style={{position:'fixed',bottom:'10px',left:'12px',zIndex:9999,background:'#16466a',border:'1px solid #2E6E8E',color:'#eaf4fb',fontSize:'0.8rem',fontWeight:700,padding:'9px 15px',borderRadius:'999px',boxShadow:'0 2px 10px rgba(0,0,0,0.45)',cursor:'pointer'}}>📋 Session Builder</button>}
  <header className="hero">
  {courtMode&&<CourtStandingBanner host={courtMode.host} court={courtMode.court}/>}
  <div className="heroNav">
    <button className="homeBtn navBackBtn" onClick={goBack}>BACK</button>
    <button className="homeBtn" onClick={()=>go('home')}>HOME</button>
    <button className="homeBtn navPlayerBtn" onClick={()=>go('playerDisplay')}>PLAYER DISPLAY</button>
    <button className="homeBtn navCompBtn" onClick={()=>go('competition')}>COMPETITION</button>
    <button className="homeBtn" onClick={()=>setSearchOpen(true)} aria-label="Search" style={{fontWeight:700}}>🔍 SEARCH</button>
  </div>
  <div><div className="eyebrow">CHECKERBOARD COACH</div><h1>Checkerboard Squash™ {APP_VERSION.split(' ')[0]}</h1><p>Sessions · Games · Players · Competition</p></div>
</header>
<main className="container">
{screen==='home'&&<Home setScreen={go}/>}
      {screen==='blindTargetScore'&&<BlindTargetScoreModule setScreen={go} players={players} setSession={setSession}/>}
      {screen==='visionPerception'&&<VisionPerceptionModule setScreen={go}/>}
      {screen==='perception'&&<PerceptionModule setScreen={go} setSession={setSession}/>}
      {screen==='peakWeek'&&<PeakWeekModule setScreen={go} setSession={setSession}/>}
      {screen==='tacticalIntentions'&&<TacticalIntentionsModule setScreen={go} setSession={setSession}/>}
      {screen==='soloPractice'&&<SoloPracticeModule setScreen={go}/>}
      {screen==='rld'&&<RLDScreen setScreen={go}/>}
      {screen==='pressure'&&<PressureModule setScreen={go}/>}
{screen==='sessions'&&<Sessions session={session} setSession={setSession} setScreen={go}/>}
{screen==='tools'&&<ToolsArchitecture setScreen={go}/>}
      {screen==='diagnosticIntervention'&&<DiagnosticIntervention setScreen={go}/>}
      {screen==='diagnostic'&&<DiagnosticTemplate setScreen={go}/>} 
      {screen==='rotational'&&<RotationalAffordanceGames setScreen={go} setSession={setSession}/>} 
      {screen==='live'&&<LiveSessionDelivery session={session} setScreen={go}/>} 
      {screen==='playerDisplay'&&<PlayerDisplayView session={session} setScreen={go}/>}
      {screen==='level0'&&<Level0Foundations setScreen={go} setSession={setSession}/>}
      {screen==='games'&&<Games setSession={setSession} setScreen={go}/>} 
      {screen==='gamesLibrary'&&<GamesLibrary setSession={setSession} setScreen={go}/>}
      {screen==='plugPlay'&&<PlugAndPlay setScreen={go} setSession={setSession}/>}
      {screen==='constraints'&&<GameConstraintsEngine setScreen={go} setSession={setSession}/>}
      {screen==='shots'&&<ShotsModule setScreen={go}/>}
      {screen==='serveReturn'&&<ServeReturnModule setScreen={go} setSession={setSession}/>}
      {screen==='bucketLob'&&<LobModule setScreen={go} setSession={setSession}/>}
      {screen==='courtMonitor'&&<CourtMonitor setScreen={go}/>}
{screen==='players'&&<PlayerHub players={players} setPlayers={setPlayers} session={session} setSession={setSession}/>}{screen==='technical'&&<UniversalOverlays setScreen={go}/>} {screen==='doubleBounce'&&<DoubleBounceTool setScreen={go}/>} {screen==='mentalSkills'&&<MentalSkillsPlaceholder setScreen={go}/>} 
{screen==='competition'&&<Competition players={players} initialInvasionFormat={lastInvasionFormat} onInvasionFormatChange={setLastInvasionFormat}/>} {screen==='storage'&&<Storage players={players} setPlayers={setPlayers} session={session} setSession={setSession}/>}
</main>

<footer className="checkerboardFooter">
  <div>© Henry Gillanders 2026 · Checkerboard Squash™</div>
  <div>MA Psychology · MSc Sport Psychology · WSF Level 3</div>
</footer>

</div>;
}

createRoot(document.getElementById('root')).render(<App/>);


